CREATE TABLE IF NOT EXISTS TaskProductLifecycle (taskProductId TEXT PRIMARY KEY REFERENCES TaskProduct(id),lifecycle TEXT NOT NULL DEFAULT 'ACTIVE',revision INTEGER NOT NULL DEFAULT 0,removedAt TEXT,removedBy TEXT,removeReason TEXT,restoredAt TEXT,restoredBy TEXT);
CREATE TABLE IF NOT EXISTS AISurfaceConfig (id TEXT PRIMARY KEY,templateAreaId TEXT NOT NULL REFERENCES TemplateZone(id),version INTEGER NOT NULL,surfaceType TEXT NOT NULL,parameters TEXT NOT NULL,createdAt TEXT NOT NULL,UNIQUE(templateAreaId,version));
CREATE TABLE IF NOT EXISTS AIRenderJob (id TEXT PRIMARY KEY,taskId TEXT NOT NULL REFERENCES Task(id),taskProductId TEXT NOT NULL REFERENCES TaskProduct(id),sourceVersionId TEXT NOT NULL REFERENCES MockupVersion(id),mockupVersionId TEXT REFERENCES MockupVersion(id),status TEXT NOT NULL,fingerprint TEXT NOT NULL,inputSnapshot TEXT NOT NULL,attemptCount INTEGER NOT NULL DEFAULT 0,errorCode TEXT,errorDetail TEXT,createdAt TEXT NOT NULL,finishedAt TEXT);
CREATE TABLE IF NOT EXISTS AIRenderAttempt (id TEXT PRIMARY KEY,jobId TEXT NOT NULL REFERENCES AIRenderJob(id),attemptNo INTEGER NOT NULL,inputSnapshot TEXT NOT NULL,outputPath TEXT,errorCode TEXT,errorDetail TEXT,durationMs INTEGER NOT NULL,metadata TEXT NOT NULL,createdAt TEXT NOT NULL,UNIQUE(jobId,attemptNo));
CREATE TABLE IF NOT EXISTS AIQualityReport (id TEXT PRIMARY KEY,attemptId TEXT NOT NULL UNIQUE REFERENCES AIRenderAttempt(id),logoScore REAL,productChangeScore REAL,geometryScore REAL,processScore REAL,result TEXT NOT NULL,reasons TEXT NOT NULL,thresholds TEXT NOT NULL,createdAt TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS AIJobFile (id TEXT PRIMARY KEY,jobId TEXT NOT NULL REFERENCES AIRenderJob(id),kind TEXT NOT NULL,filePath TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS BatchRenderMode (batchJobId TEXT PRIMARY KEY REFERENCES BatchJob(id),mode TEXT NOT NULL);
